258	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
259	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
260	        if (currentOwner == null) {
261	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	        }
263	        normalizeAddress(ownerFieldsDto);
264	        currentOwner.setAddress(ownerFieldsDto.getAddress());
265	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
266	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
267	        currentOwner.setCity(ownerFieldsDto.getCity());
268	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
269	        currentOwner.setLastName(ownerFieldsDto.getLastName());
270	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
271	        normalizeEmail(ownerFieldsDto);
272	        currentOwner.setEmail(ownerFieldsDto.getEmail());
273	        this.clinicService.saveOwner(currentOwner);
274	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
275	    }
