355	    /**
356	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
357	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
358	     * does not catch). The names of all offending fields are collected so the caller receives a
359	     * 400 response whose {@code errors} array lists each one.
360	     */
361	    /**
362	     * Returns the trimmed {@code Idempotency-Key} header of the current request, or {@code null} when
363	     * the header is absent, blank or there is no active request. A present key opts a create into the
364	     * idempotent-repeat behaviour tracked by {@link #idempotentCreates}.
365	     */
366	    private String idempotencyKey() {
367	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
368	            return null;
369	        }
370	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
371	        if (key == null || key.trim().isEmpty()) {
372	            return null;
373	        }
374	        return key.trim();
375	    }
