377	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
378	        List<String> missingFields = new ArrayList<>();
379	        if (isBlank(ownerFieldsDto.getFirstName())) {
380	            missingFields.add("firstName");
381	        }
382	        if (isBlank(ownerFieldsDto.getLastName())) {
383	            missingFields.add("lastName");
384	        }
385	        if (isBlank(ownerFieldsDto.getAddress())) {
386	            missingFields.add("address");
387	        }
388	        if (isBlank(ownerFieldsDto.getCity())) {
389	            missingFields.add("city");
390	        }
391	        if (isBlank(ownerFieldsDto.getTelephone())) {
392	            missingFields.add("telephone");
393	        }
394	        if (!missingFields.isEmpty()) {
395	            throw new InvalidOwnerFieldsException(missingFields);
396	        }
397	    }
398	
399	    private static boolean isBlank(String value) {
400	        return value == null || value.trim().isEmpty();
401	    }
402	
403	    /**
404	     * Normalizes an owner's address on create, supporting both the structured form
405	     * ({@code addressLine1} plus optional {@code addressLine2}) and the flat {@code address} form kept
406	     * for backward compatibility. Whichever fields are supplied are canonicalized in place - trimmed,
407	     * internal whitespace runs collapsed to a single space, upper-cased and common street-type
408	     * abbreviations expanded as whole tokens ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
409	     * {@code AVE}->{@code AVENUE}). The canonical {@code addressLine1}/{@code addressLine2} are written
410	     * back, and the composed {@code address} - the normalized {@code addressLine1} with a single space
411	     * and the normalized {@code addressLine2} appended when present, falling back to the normalized
412	     * flat {@code address} when no structured line is given - is written onto the request so it is what
413	     * gets validated, compared, stored and returned. Running before the required-field check means an
414	     * address that is blank in both forms after normalization is rejected like a missing one.
415	     */
416	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
417	        String line1 = canonicalAddress(ownerFieldsDto.getAddressLine1());
418	        String line2 = canonicalAddress(ownerFieldsDto.getAddressLine2());
419	        String flat = canonicalAddress(ownerFieldsDto.getAddress());
420	        ownerFieldsDto.setAddressLine1(line1);
421	        ownerFieldsDto.setAddressLine2(line2);
422	        ownerFieldsDto.setAddress(composeAddress(line1, line2, flat));
423	    }
424	
425	    /**
426	     * Composes the effective address, preferring the structured form: when {@code line1} is present
427	     * (non-blank) the result is {@code line1}, with a single space and {@code line2} appended when
428	     * {@code line2} is present; otherwise the flat {@code address} is used. All three inputs are
429	     * expected to be already canonicalized. Returns the flat value (which may be {@code null} or blank,
430	     * left for the required-field check to reject) when no structured line is supplied.
431	     */
432	    private static String composeAddress(String line1, String line2, String flat) {
433	        if (line1 != null && !line1.isBlank()) {
434	            if (line2 != null && !line2.isBlank()) {
435	                return line1 + " " + line2;
436	            }
437	            return line1;
438	        }
439	        return flat;
440	    }
441	
442	    /**
443	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
444	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
445	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
446	     * address is returned unchanged, making it safe to apply to stored values during comparison.
447	     */
448	    private static String canonicalAddress(String address) {
449	        if (address == null) {
450	            return null;
451	        }
452	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
453	        if (collapsed.isEmpty()) {
454	            return "";
455	        }
456	        String[] tokens = collapsed.split(" ");
457	        StringBuilder sb = new StringBuilder(collapsed.length());
458	        for (int i = 0; i < tokens.length; i++) {
459	            if (i > 0) {
460	                sb.append(' ');
461	            }
462	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
463	        }
464	        return sb.toString();
465	    }
466	
467	    /**
468	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
469	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
470	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
471	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
472	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
473	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
474	     * written back onto the request so it is what gets stored and returned. Any value that cannot
475	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
476	     * {@code telephone}.
477	     */
478	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
479	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
480	    }
481	
482	    /**
483	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
484	     * (400) naming {@code telephone} when it cannot form a valid number.
485	     */
486	    private static String toE164(String telephone) {
487	        if (telephone == null) {
488	            throw new InvalidOwnerFieldsException(List.of("telephone"));
489	        }
490	        boolean hasCountryCode = telephone.trim().startsWith("+");
491	        String digits = telephone.replaceAll("\\D", "");
492	        String countryCode;
493	        String national;
494	        if (hasCountryCode) {
495	            countryCode = matchCountryCode(digits);
496	            national = digits;
497	        } else {
498	            countryCode = "61";
499	            if (digits.startsWith("0")) {
500	                digits = digits.substring(1);
501	            }
502	            national = "61" + digits;
503	        }
504	        if (!national.matches("[0-9]{8,15}")) {
505	            throw new InvalidOwnerFieldsException(List.of("telephone"));
506	        }
507	        if (countryCode != null) {
508	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
509	            if (requiredLength != null
510	                && national.length() - countryCode.length() != requiredLength) {
511	                throw new InvalidOwnerFieldsException(List.of("telephone"));
512	            }
513	        }
514	        return "+" + national;
515	    }
516	
517	    /**
518	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
519	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
520	     * the number is not length-checked against a country.
521	     */
522	    private static String matchCountryCode(String digits) {
523	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
524	            .filter(digits::startsWith)
525	            .max(Comparator.comparingInt(String::length))
526	            .orElse(null);
527	    }
528	
529	    /**
530	     * Rejects creating an owner that duplicates an existing one, either as a household duplicate or
531	     * as an exact identity duplicate. The household is now keyed on the computed {@code householdId}
532	     * (a deterministic function of the normalized last name and postcode, see
533	     * {@link #computeHouseholdId}), so any existing owner already carrying the same {@code householdId}
534	     * belongs to the same household and makes the new owner a household duplicate. Independently, an
535	     * exact match on the derived {@code identityKey} - {@code normalizedTelephone + '|' + (email or
536	     * empty) + '|' + (householdId or empty)} - is also a duplicate; this still catches owners with no
537	     * postcode (and therefore no household) that share a telephone and email. Both checks are a 409.
538	     *
539	     * <p>Owners flagged {@code deleted} (soft-deleted via {@code DELETE /api/owners/{id}}) are skipped
540	     * entirely, so a normally-blocking duplicate is allowed when the only matching owner has been
541	     * deleted.
542	     *
543	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block: a request that opts in
544	     * is allowed through even when it lands in an existing household, so it is created as a declared
545	     * household member rather than rejected. The incoming telephone and email have already been
546	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}; each existing owner's key
547	     * is derived the same way before comparison. A match results in a 409 response naming
548	     * {@code identityKey}.
549	     */
550	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId) {
551	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
552	            return;
553	        }
554	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
555	        for (Owner existing : this.clinicService.findAllOwners()) {
556	            if (Boolean.TRUE.equals(existing.getDeleted())) {
557	                continue;
558	            }
559	            boolean householdDuplicate = householdId != null && householdId.equals(existing.getHouseholdId());
560	            if (householdDuplicate || identityKey.equals(existingIdentityKey(existing))) {
561	                throw new DuplicateOwnerIdentityException(identityKey);
562	            }
563	        }
564	    }
565	
566	    /**
567	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
568	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
569	     * are expected to already be in their normalized (E.164, lower-cased) forms.
570	     */
571	    private static String identityKey(String telephone, String email, String householdId) {
572	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
573	    }
574	
575	    /**
576	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
577	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
578	     * the stored email is lower-cased, and the stored household id is used as-is.
579	     */
580	    private static String existingIdentityKey(Owner existing) {
581	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
582	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
583	        return identityKey(telephone, email, existing.getHouseholdId());
584	    }
585	
586	    private static String orEmpty(String value) {
587	        return value == null ? "" : value;
588	    }
589	
590	    /**
591	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
592	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
593	     */
594	    private static String normalizeExisting(String telephone) {
595	        try {
596	            return toE164(telephone);
597	        } catch (InvalidOwnerFieldsException ex) {
598	            return null;
599	        }
600	    }
601	
602	    /**
603	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
604	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
605	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
606	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
607	     */
608	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
609	        String city = ownerFieldsDto.getCity();
610	        int count = 0;
611	        for (Owner existing : this.clinicService.findAllOwners()) {
612	            if (city.equalsIgnoreCase(existing.getCity())) {
613	                count++;
614	            }
615	        }
616	        if (count >= MAX_OWNERS_PER_CITY) {
617	            throw new OwnerCityAtCapacityException(city);
618	        }
619	    }
620	
621	    /**
622	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
623	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
624	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
625	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
626	     */
627	    private void rejectDailyLimitReached(LocalDate registrationDate) {
628	        int count = 0;
629	        for (Owner existing : this.clinicService.findAllOwners()) {
630	            if (registrationDate.equals(existing.getRegistrationDate())) {
631	                count++;
632	            }
633	        }
634	        if (count >= MAX_OWNERS_PER_DAY) {
635	            throw new DailyOwnerLimitReachedException(registrationDate);
636	        }
637	    }
638	
639	    /**
640	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
641	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
642	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
643	     */
644	    private static String normalizeForComparison(String value) {
645	        if (value == null) {
646	            return "";
647	        }
648	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
649	    }
650	
651	    /**
652	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
653	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
654	     * written back onto the request so that is what gets stored and returned. A present but invalid
655	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
656	     */
657	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
658	        String email = ownerFieldsDto.getEmail();
659	        if (email == null) {
660	            return;
661	        }
662	        String trimmed = email.trim();
663	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
664	            throw new InvalidOwnerFieldsException(List.of("email"));
665	        }
666	        String normalized = trimmed.toLowerCase(Locale.ROOT);
667	        String domain = normalized.substring(normalized.indexOf('@') + 1);
668	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
669	            throw new InvalidOwnerFieldsException(List.of("email"));
670	        }
671	        ownerFieldsDto.setEmail(normalized);
672	    }
673	
674	    /**
675	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
676	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
677	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
678	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
679	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
680	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
681	     * as-is so it is stored and returned.
682	     */
683	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
684	        String postcode = ownerFieldsDto.getPostcode();
685	        if (postcode == null) {
686	            return;
687	        }
688	        if (!postcode.matches("[0-9]{4}")) {
689	            throw new InvalidOwnerFieldsException(List.of("postcode"));
690	        }
691	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
692	        if (range != null) {
693	            int value = Integer.parseInt(postcode);
694	            if (value < range[0] || value > range[1]) {
695	                throw new InvalidOwnerFieldsException(List.of("postcode"));
696	            }
697	        }
698	    }
699	
700	    /**
701	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
702	     * day. When the caller supplies no value it defaults to the server's current date; a value
703	     * provided in the request is kept. A supplied value later than the server's current date is
704	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
705	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
706	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
707	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
708	     * every value derived from the registration date is based on.
709	     */
710	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
711	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
712	        if (effective == null) {
713	            effective = LocalDate.now();
714	        }
715	        else if (effective.isAfter(LocalDate.now())) {
716	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
717	        }
718	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
719	    }
720	
721	    /**
722	     * The fixed public-holiday calendar. A registration date landing on one of these days is rolled
723	     * forward, just like a weekend, until it reaches a non-holiday business day.
724	     */
725	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
726	        LocalDate.of(2026, 1, 1),
727	        LocalDate.of(2026, 1, 26),
728	        LocalDate.of(2026, 4, 25),
729	        LocalDate.of(2026, 12, 25),
730	        LocalDate.of(2026, 12, 28));
731	
732	    /**
733	     * Rolls a date forward onto a business day: a Saturday, Sunday or listed public holiday is
734	     * advanced one day at a time until it reaches the next non-holiday business day; a weekday that
735	     * is not a holiday is returned unchanged.
736	     */
737	    private static LocalDate toBusinessDay(LocalDate date) {
738	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
739	            date = date.plusDays(1);
740	        }
741	        return date;
742	    }
743	
744	    /**
745	     * Returns whether the given date falls on a Saturday or Sunday.
746	     */
747	    private static boolean isWeekend(LocalDate date) {
748	        return switch (date.getDayOfWeek()) {
749	            case SATURDAY, SUNDAY -> true;
750	            default -> false;
751	        };
752	    }
753	
754	    /**
755	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
756	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
757	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
758	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
759	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
760	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
761	     * pure function of region, telephone and last name.
762	     */
763	    private void assignCustomerCode(Owner owner) {
764	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
765	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
766	        owner.setCustomerCode(deduplicateCustomerCode(region + "-" + hash8));
767	    }
768	
769	    /**
770	     * Returns {@code customerCode} unchanged when no existing owner already carries it; otherwise
771	     * appends {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by
772	     * any existing owner. Compared against the pre-existing owners, so the returned code is unique
773	     * among them.
774	     */
775	    private String deduplicateCustomerCode(String customerCode) {
776	        Set<String> existing = new HashSet<>();
777	        for (Owner owner : this.clinicService.findAllOwners()) {
778	            if (owner.getCustomerCode() != null) {
779	                existing.add(owner.getCustomerCode());
780	            }
781	        }
782	        if (!existing.contains(customerCode)) {
783	            return customerCode;
784	        }
785	        int n = 2;
786	        while (existing.contains(customerCode + "-" + n)) {
787	            n++;
788	        }
789	        return customerCode + "-" + n;
790	    }
791	
792	    /**
793	     * Assigns the owner's {@code membershipNumber} on create, formatted
794	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the fiscal year of
795	     * the business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July, e.g. a
796	     * registration on 2026-08-03 falls in fiscal year 2027 and yields {@code 'NSW-1A2B3C4D-M27'}).
797	     * Assigned after {@link #assignCustomerCode} and once {@code registrationDate} has been
798	     * defaulted, so both inputs are present.
799	     */
800	    private void assignMembershipNumber(Owner owner) {
801	        String yy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
802	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
803	    }
804	
805	    /**
806	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
807	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
808	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
809	     */
810	    private void assignNamesakeCount(Owner owner) {
811	        String firstName = owner.getFirstName();
812	        String lastName = owner.getLastName();
813	        int count = 0;
814	        for (Owner existing : this.clinicService.findAllOwners()) {
815	            if (firstName.equalsIgnoreCase(existing.getFirstName())
816	                && lastName.equalsIgnoreCase(existing.getLastName())) {
817	                count++;
818	            }
819	        }
820	        owner.setNamesakeCount(count);
821	    }
822	
823	    /**
824	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
825	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
826	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
827	     * {@value #TENURE_LEVEL_THRESHOLD_FISCAL_YEARS} elapsed fiscal year. The points are then mapped to a level of 1 (0-1
828	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
829	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
830	     * tenure, so the tenure bonus never applies on create.
831	     */
832	    private void assignMembership(Owner owner) {
833	        int points = 0;
834	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
835	            points += 2;
836	        }
837	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
838	            points += 1;
839	        }
840	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
841	            points += 2;
842	        }
843	        if (tenureFiscalYears(owner) > TENURE_LEVEL_THRESHOLD_FISCAL_YEARS) {
844	            points += 3;
845	        }
846	        owner.setMembershipPoints(points);
847	        owner.setMembershipLevel(membershipLevelForPoints(points));
848	    }
849	
850	    /**
851	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
852	     * 4-5, and 4 for 6 or more points.
853	     */
854	    private int membershipLevelForPoints(int points) {
855	        if (points <= 1) {
856	            return 1;
857	        }
858	        if (points <= 3) {
859	            return 2;
860	        }
861	        if (points <= 5) {
862	            return 3;
863	        }
864	        return 4;
865	    }
866	
867	    /**
868	     * The tenure, in elapsed fiscal years, of a newly created owner. Tenure accrues from membership
869	     * over time, and a new owner has not been a member for any elapsed fiscal year yet, so this is
870	     * always {@code 0} on create (regardless of any backdated {@code registrationDate}).
871	     */
872	    private long tenureFiscalYears(Owner owner) {
873	        return 0L;
874	    }
875	
876	    /**
877	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
878	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
879	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
880	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
881	     * pre-existing owners for that day.
882	     */
883	    private void assignBulkSignupWarning(Owner owner) {
884	        LocalDate registrationDate = owner.getRegistrationDate();
885	        int count = 0;
886	        for (Owner existing : this.clinicService.findAllOwners()) {
887	            if (registrationDate.equals(existing.getRegistrationDate())) {
888	                count++;
889	            }
890	        }
891	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
892	    }
893	
894	    /**
895	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
896	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
897	     * possible duplicate when an existing owner shares its {@code lastName} (compared
898	     * case-insensitively) and its {@code postcode} (a present, exact match) while carrying a different
899	     * {@code telephone}. When such an owner exists, {@code possibleDuplicate} is set to {@code true}
900	     * and {@code possibleDuplicateOf} to that owner's id (the lowest id when several match); otherwise
901	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is left {@code null}.
902	     * Computed before the new owner is persisted, so it considers only the pre-existing owners.
903	     *
904	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
905	     * has deliberately opted into an existing household, so its shared last name and postcode are
906	     * expected rather than a suspected duplicate.
907	     */
908	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
909	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
910	            owner.setPossibleDuplicate(false);
911	            owner.setPossibleDuplicateOf(null);
912	            return;
913	        }
914	        String lastName = owner.getLastName();
915	        String postcode = owner.getPostcode();
916	        String telephone = owner.getTelephone();
917	        Integer matchId = null;
918	        if (postcode != null) {
919	            for (Owner existing : this.clinicService.findAllOwners()) {
920	                if (lastName.equalsIgnoreCase(existing.getLastName())
921	                    && postcode.equals(existing.getPostcode())
922	                    && !postcode.isBlank()
923	                    && !java.util.Objects.equals(telephone, existing.getTelephone())
924	                    && existing.getId() != null
925	                    && (matchId == null || existing.getId() < matchId)) {
926	                    matchId = existing.getId();
927	                }
928	            }
929	        }
930	        owner.setPossibleDuplicate(matchId != null);
931	        owner.setPossibleDuplicateOf(matchId);
932	    }
933	
934	    /**
935	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
936	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
937	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
938	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
939	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
940	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
941	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
942	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
943	     * ({@link #assignHouseholdMembership}).
944	     */
945	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
946	        String postcode = ownerFieldsDto.getPostcode();
947	        if (postcode == null || postcode.isBlank()) {
948	            return null;
949	        }
950	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
951	        return shaHexUpper(lastName + "|" + postcode, 12);
952	    }
953	
954	    /**
955	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
956	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
957	     * every existing owner already carrying the same identifier. Runs after the owner's
958	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
959	     * Left {@code null} when the owner belongs to no household.
960	     */
961	    private void assignHouseholdMembership(Owner owner) {
962	        String householdId = owner.getHouseholdId();
963	        if (householdId == null || householdId.isBlank()) {
964	            owner.setHouseholdMemberCount(null);
965	            return;
966	        }
967	        int count = 1;
968	        for (Owner existing : this.clinicService.findAllOwners()) {
969	            if (householdId.equals(existing.getHouseholdId())) {
970	                count++;
971	            }
972	        }
973	        owner.setHouseholdMemberCount(count);
974	    }
975	
976	    /**
977	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
978	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
979	     * identifier, both stable functions of their inputs.
980	     */
981	    private static String shaHexUpper(String input, int length) {
982	        try {
983	            byte[] digest = MessageDigest.getInstance("SHA-256")
984	                .digest(input.getBytes(StandardCharsets.UTF_8));
985	            StringBuilder hex = new StringBuilder(digest.length * 2);
986	            for (byte b : digest) {
987	                hex.append(String.format("%02x", b));
988	            }
989	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
990	        } catch (NoSuchAlgorithmException ex) {
991	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
992	        }
993	    }
994	}
